window.HOEREN_TESTS[65] = {"id":"handwerker-im-haus","name":"Handwerker im Haus","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist Klempner Schmidt. Ich komme morgen wegen der Heizung. Aber nicht um 9 Uhr wie geplant, und auch nicht um 13 Uhr, sondern erst um 11 Uhr — ein Notfall vorher. Bitte seien Sie zu Hause und stellen Sie das Wasser ab. Es dauert ungefähr zwei Stunden. Bis morgen!","gender":"m","q":"Wann kommt der Klempner?","opts":["Um 9 Uhr.","Um 13 Uhr.","Um 11 Uhr."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Pass auf, bei mir tropft der Wasserhahn in der Küche die ganze Nacht. Die Heizung ist nicht kalt, und das Licht geht auch. Ich werde verrückt! Kennst du einen guten Handwerker? Nicht zu teuer und der schnell kommt. Ruf zurück, ich brauche dringend Hilfe!","gender":"m","q":"Was ist Markus' Problem?","opts":["Das Licht geht nicht.","Die Heizung ist kalt.","Der Wasserhahn tropft."],"correct":2},{"transcript":"Achtung Bewohner: Am Donnerstag kommt der Elektriker ins Haus. Zwischen 8 und 12 Uhr wird der Strom kurz abgeschaltet — für neue Zähler. Das Wasser bleibt an, und die Heizung wird nicht repariert. Bitte schalten Sie alle Geräte vorher aus, Computer und Kühlschrank besonders. Der Aufzug fährt in dieser Zeit nicht. Danke für Ihr Verständnis!","gender":"f","q":"Was passiert am Donnerstag?","opts":["Das Wasser wird abgestellt.","Der Strom wird abgeschaltet.","Die Heizung wird repariert."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Der Maler war heute da und hat das Wohnzimmer gestrichen. Sieht toll aus, jetzt ganz hell! Das Schlafzimmer und die Küche macht er erst nächste Woche. Komm doch mal vorbei und schau es dir an. Vielleicht hast du auch Lust auf neue Farben?","gender":"f","q":"Was hat der Maler gemacht?","opts":["Das Schlafzimmer gestrichen.","Das Wohnzimmer gestrichen.","Die Küche gestrichen."],"correct":1},{"transcript":"Liebe Kunden: Unsere Handwerker-Firma bietet jetzt einen Notdienst rund um die Uhr, also nicht nur tagsüber und nicht nur am Wochenende. Bei Wasserschaden oder Stromausfall sind wir auch nachts da. Der Notdienst kostet mehr als normal. Normale Termine bitte weiter zu den Bürozeiten buchen. Speichern Sie unsere Nummer!","gender":"m","q":"Wann ist der Notdienst da?","opts":["Rund um die Uhr.","Nur tagsüber.","Nur am Wochenende."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer braucht wen? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Im Haus ist diese Woche einiges kaputt und die Nummern liegen bereit."},{"speaker":"Lisa","gender":"f","text":"Dann rufen wir die Leute nacheinander an. Ich will das lieber in Ruhe planen."},{"speaker":"Lukas","gender":"m","text":"Ich brauche einen Klempner. Unter der Spüle tropft es schon seit Montag."},{"speaker":"Lisa","gender":"f","text":"Für den Flur hole ich einen Elektriker. Das Licht geht am Abend immer aus."},{"speaker":"Lukas","gender":"m","text":"Kommt auch ein Schlosser zu uns ins Haus?"},{"speaker":"Lisa","gender":"f","text":"Nein. Einen Schlosser brauchen wir nicht."},{"speaker":"Lukas","gender":"m","text":"Tom will das Wohnzimmer endlich heller und freundlicher haben."},{"speaker":"Lisa","gender":"f","text":"Tom bestellt einen Maler. Die Wände im Wohnzimmer werden bei ihm hellgrau."},{"speaker":"Lukas","gender":"m","text":"Sara hat eine wacklige Tür im Schlafzimmer und ärgert sich."},{"speaker":"Lisa","gender":"f","text":"Sara ruft einen Tischler an. Er soll die Tür wieder fest in den Rahmen setzen."},{"speaker":"Lukas","gender":"m","text":"Rufen wir einen Fensterputzer für die hohen Scheiben?"},{"speaker":"Lisa","gender":"f","text":"Nein. Einen Fensterputzer rufen wir auch nicht. Das machen wir selbst am Samstag."},{"speaker":"Lukas","gender":"m","text":"Der Regen kommt bei Tim durch die Decke."},{"speaker":"Lisa","gender":"f","text":"Tim sucht einen Dachdecker. Zwei Ziegel liegen schon unten im Garten."},{"speaker":"Lukas","gender":"m","text":"Dann stehen fünf Namen ordentlich auf dem Zettel."},{"speaker":"Lisa","gender":"f","text":"Ich lege den Zettel neben das Telefon in der Küche."}],"options":[{"letter":"a","text":"Schlosser"},{"letter":"b","text":"Maler"},{"letter":"c","text":"Dachdecker"},{"letter":"d","text":"Elektriker"},{"letter":"e","text":"Fensterputzer"},{"letter":"f","text":"Gärtner"},{"letter":"g","text":"Klempner"},{"letter":"h","text":"Fliesenleger"},{"letter":"i","text":"Tischler"}],"items":[{"person":"Lukas","correct":"g"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"b"},{"person":"Sara","correct":"i"},{"person":"Tim","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, was kostet der Besuch bei uns zu Hause?"},{"speaker":"Handwerker","gender":"m","text":"Die Anfahrt kostet 30 Euro, dann 60 Euro pro Stunde. Zusammen sind das 90 Euro bei einer Stunde Arbeit."},{"speaker":"Kundin","gender":"f","text":"Wie lange dauert es ungefähr?"},{"speaker":"Handwerker","gender":"m","text":"Ungefähr eine Stunde, also Anfahrt 30 Euro und Arbeit 60 Euro."},{"speaker":"Kundin","gender":"f","text":"Gut, dann kommen Sie bitte. Die 30 Euro für die Anfahrt sind okay."}],"q":"Was kostet die Anfahrt?","opts":["60 Euro.","30 Euro.","90 Euro."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, können Sie heute noch kommen? Das Rohr tropft."},{"speaker":"Klempnerin","gender":"f","text":"Heute leider nicht, ich bin voll. Übermorgen geht es, aber das ist spät."},{"speaker":"Mann","gender":"m","text":"Und morgen? Morgen wäre besser als übermorgen."},{"speaker":"Klempnerin","gender":"f","text":"Morgen früh um 8 geht es. Ist das okay?"},{"speaker":"Mann","gender":"m","text":"Ja, morgen früh um 8 ist gut. Danke, dann komme ich nicht heute."}],"q":"Wann kommt die Klempnerin?","opts":["Heute.","Übermorgen.","Morgen früh."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, die Waschmaschine läuft aus. Soll ich den Strom abschalten oder die Maschine öffnen?"},{"speaker":"Techniker","gender":"m","text":"Öffnen Sie die Maschine nicht, und den Strom müssen Sie jetzt nicht abschalten. Seit wann läuft sie aus?"},{"speaker":"Frau","gender":"f","text":"Seit heute Morgen, das Wasser steht in der Küche."},{"speaker":"Techniker","gender":"m","text":"Stellen Sie sofort das Wasser ab, ich komme. Nicht den Strom, das Wasser!"},{"speaker":"Frau","gender":"f","text":"Okay, ich stelle das Wasser ab. Danke, kommen Sie schnell."}],"q":"Was soll die Frau sofort tun?","opts":["Den Strom abschalten.","Die Maschine öffnen.","Das Wasser abstellen."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Was soll ich tun, reparieren oder neu kaufen? Oder einfach nichts tun?"},{"speaker":"Techniker","gender":"m","text":"Nichts tun ist keine gute Idee, das Problem wird größer. Die Reparatur kostet 200 Euro."},{"speaker":"Kunde","gender":"m","text":"Und ein neues Gerät?"},{"speaker":"Techniker","gender":"m","text":"Ab 350 Euro. Ich würde reparieren, das ist günstiger und das Gerät ist noch gut."},{"speaker":"Kunde","gender":"m","text":"Gut, dann reparieren wir. Neu kaufen mache ich nicht."}],"q":"Was empfiehlt der Techniker?","opts":["Reparieren.","Neu kaufen.","Nichts tun."],"correct":0},{"lines":[{"speaker":"Mieterin","gender":"f","text":"Guten Tag, wer zahlt die Heizungs-Reparatur, die Mieterin oder der Vermieter? Oder beide zusammen?"},{"speaker":"Hausmeister","gender":"m","text":"Bei der Heizung zahlt der Vermieter, nicht die Mieterin und nicht beide zusammen."},{"speaker":"Mieterin","gender":"f","text":"Und wenn ich etwas kaputt mache?"},{"speaker":"Hausmeister","gender":"m","text":"Dann zahlen Sie selbst. Aber die Heizung ist Sache des Vermieters."},{"speaker":"Mieterin","gender":"f","text":"Verstehe, der Vermieter zahlt die Heizung. Danke für die Info."}],"q":"Wer zahlt die Heizungs-Reparatur?","opts":["Der Vermieter.","Die Mieterin.","Beide zusammen."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Fischer, einem Klempnermeister. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Fischer, Sie sind seit 25 Jahren Klempner. Gibt es genug Nachwuchs in Ihrem Beruf?"},{"speaker":"Fischer","gender":"m","text":"Leider nein, das ist ein großes Problem. Junge Leute wollen lieber studieren als ein Handwerk lernen. Dabei verdient man als Handwerker heute sehr gut. Ich suche dringend Lehrlinge, finde aber kaum welche. Das macht mir Sorgen."},{"speaker":"Reporterin","gender":"f","text":"Wie lange müssen die Kunden auf einen Termin warten?"},{"speaker":"Fischer","gender":"m","text":"Bei normalen Sachen oft mehrere Wochen. Wir sind völlig ausgebucht. Bei einem Notfall — wenn das Wasser läuft — kommen wir natürlich sofort. Aber wer nur einen tropfenden Hahn hat, muss leider Geduld haben. Das ärgert viele Kunden."},{"speaker":"Reporterin","gender":"f","text":"Was ist die häufigste Reparatur?"},{"speaker":"Fischer","gender":"m","text":"Verstopfte Rohre, ganz klar. Die Leute werfen Sachen in die Toilette, die da nicht hingehören. Und tropfende Wasserhähne. Beides ist eigentlich leicht zu reparieren. Schlimmer sind Wasserschäden — die kosten richtig viel und dauern lange."},{"speaker":"Reporterin","gender":"f","text":"Können die Leute manche Sachen selbst machen?"},{"speaker":"Fischer","gender":"m","text":"Kleine Dinge ja, eine Wasserhahn-Dichtung wechseln zum Beispiel. Aber bei Gas und größeren Sachen sollte man immer einen Fachmann holen. Das ist zu gefährlich. Ich habe schon viele Schäden gesehen, weil jemand selbst gebastelt hat. Das wird dann teuer."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie Hausbesitzern?"},{"speaker":"Fischer","gender":"m","text":"Lassen Sie die Heizung regelmäßig warten, am besten jeden Herbst. Das verhindert teure Schäden im Winter. Und bei einem kleinen Problem nicht warten, bis es groß wird. Vorsorge ist immer billiger als Reparatur. Das vergessen viele."}],"items":[{"q":"Herr Fischer findet leicht neue Lehrlinge.","correct":"nein"},{"q":"Bei einem Notfall mit Wasser kommt er sofort.","correct":"ja"},{"q":"Verstopfte Rohre sind eine häufige Reparatur.","correct":"ja"},{"q":"Er rät, Gas-Reparaturen selbst zu machen.","correct":"nein"},{"q":"Er empfiehlt, die Heizung regelmäßig warten zu lassen.","correct":"ja"}]}]};
